"""Self-contained six-slide local review demo from the actual UI export and QA captures."""
import base64,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
QA=ROOT/'docs/qa/atlas/round-4'
def uri(path,mime='image/png'):return 'data:'+mime+';base64,'+base64.b64encode(path.read_bytes()).decode()
def img(name,cls=''):return f'<img class="{cls}" src="{uri(QA/name)}" alt="Actual RIMWAKE production screenshot">'
data=json.loads((ROOT/'docs/qa/atlas/final/default-comparison.json').read_text());summaries=data['summaries']
slides=[]
def slide(title,body):
 n=len(slides)+1;slides.append(f'<section class="slide"><header>RIMWAKE / LUNAR LANDING SITE NAVIGATOR</header><h1>{title}</h1>{body}<footer><span>Local review / science provisional / team details require owner completion before publication</span><span>{n:02} / 06</span></footer></section>')
slide('THE PLACE. THE DATE. THE DIFFERENCE.','<div class="hero">'+img('landing-1440.png')+'</div><p class="caption">An immersive atlas for understanding what a changed lunar mission window changes.</p>')
slide('A CHANGED DATE. A NEW QUESTION.','<div class="columns"><div><h2>Compare the window.<br>Then move the mission.</h2><p>Two locations can have different Sun and Earth conditions at one shared time.</p><p>RIMWAKE compares the original window with the same duration after a delay.</p><p class="note">Six documented viewpoints. Ninety days of archived NASA/JPL positions. Geometric reference horizon only.</p></div>'+img('atlas-region-1440.png','landscape')+'</div>')
counts=[f"{row['joint']['above']}/{row['joint']['expected']}" for row in summaries]
slide('THREE DAYS CHANGE THE COMPARISON.','<div class="wide comparison">'+img('comparison-1440.png')+'</div><p class="caption">14-21 November 2026, shifted to 17-24 November. Jointly above hourly samples: Odysseus '+counts[0]+' to '+counts[2]+'; Athena '+counts[1]+' to '+counts[3]+'. Inclusive sampled endpoints, not continuous availability.</p>')
slide('ONE CLOCK. EVERY VIEW.','<div class="wide">'+img('timeline-1440.png')+'</div><p class="caption">Locate the observers, move a window, inspect an exact sample, filter the timeline and follow source crossing brackets. No numerical position interpolation.</p>')
slide('THE EVIDENCE STAYS WITH THE RESULT.','<div class="columns"><div><h2>The source.<br>The sample.<br>The limit.</h2><p>25,932 archived hourly readings.<br>NASA NSSDCA locations.<br>JPL Horizons apparent airless directions.</p><p>Share a reproducible comparison, export source-linked samples, or print a brief.</p><p class="note">Hashes and raw responses establish source consistency. Independent ephemeris validation and exact frame reconciliation remain open.</p></div>'+img('evidence-390.png','portrait')+'</div>')
slide('MAKE THE TRADEOFF UNDERSTANDABLE.','<div class="value"><div><h2>LOCATE.</h2><p>Find the viewpoint in a coherent geographic context.</p></div><div><h2>COMPARE.</h2><p>See how a schedule shift changes sampled conditions.</p></div><div><h2>VERIFY.</h2><p>Inspect and export the source behind the result.</p></div></div><p>For educators, the public and technically curious explorers.</p><p class="note">Hypothetical ellipsoid observers. Terrain, finite discs, eclipses, usable power and RF performance are excluded. NASA imagery and NASA/JPL/NSSDCA data are credited; no endorsement is implied. Owner direction; Codex assisted implementation, processing, tests and text. No generated imagery or audio. Local demonstration, not a deployed or submitted project.</p>')
display=uri(ROOT/'node_modules/@fontsource/barlow-condensed/files/barlow-condensed-latin-600-normal.woff2','font/woff2');body=uri(ROOT/'node_modules/@fontsource/ibm-plex-sans/files/ibm-plex-sans-latin-400-normal.woff2','font/woff2')
css='@font-face{font-family:Display;src:url(FONT)}@font-face{font-family:Body;src:url(BODY)}*{box-sizing:border-box}body{margin:0;background:#090f15;color:#eeeade;font-family:Body,Arial}.slide{width:1280px;height:720px;padding:32px 48px 45px;position:relative;break-after:page;overflow:hidden}header{font-size:12px;letter-spacing:.12em;color:#b7c7d2}h1{font:600 58px/.97 Display;margin:20px 0 24px}h2{font:600 43px/1.05 Display;margin:0 0 22px}p{font-size:22px;line-height:1.55;margin:0 0 20px;color:#c6d0d7}.hero{height:470px;overflow:hidden}.hero img{width:100%;height:100%;object-fit:cover;object-position:center 30%}.caption{font-size:17px;line-height:1.5;margin-top:15px}.columns{display:grid;grid-template-columns:1fr 530px;gap:55px;height:485px}.landscape{width:100%;height:485px;object-fit:contain;align-self:center}.portrait{max-width:100%;height:485px;object-fit:contain;justify-self:center}.note{font-size:16px;line-height:1.65;color:#afc0cc}.wide{height:470px;overflow:hidden}.wide img{width:100%;height:100%;object-fit:contain}.comparison{height:411px;margin-top:24px;margin-bottom:35px}.comparison img{object-fit:cover;object-position:center 59%}.value{display:grid;grid-template-columns:repeat(3,1fr);gap:40px;margin:65px 0 50px}.value>div{border-top:1px solid #617386;padding-top:25px}.value p{font-size:23px}footer{position:absolute;bottom:18px;left:48px;right:48px;display:flex;justify-content:space-between;font-size:10px;color:#a7b8c5}@page{size:1280px 720px;margin:0}@media screen{.slide{margin:0 auto 20px;box-shadow:0 0 0 1px #3d4d5d}}'.replace('FONT',display).replace('BODY',body)
(ROOT/'docs/demo-slides.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>RIMWAKE mission atlas local demonstration</title><style>'+css+'</style>'+''.join(slides)+'</html>',encoding='utf-8')
print('Created six self-contained slides from actual source-exported metrics and production screenshots.')
